App.register({group:'studio',label:'AI 创作工作台',icon:'✳',routes:[
{path:'studio/brief',title:'AI 创作助手',icon:'✳',permission:'studio',render(){
 const p=App.project();if(!p)return UI.page('CREATIVE DESK / 01','尚未选择项目','先创建项目或切换到已授权的项目，再开始创作。',UI.btn('创建项目','project:new','btn-primary'),`<div class="card">${UI.empty('没有可用项目','当前租户和身份范围内没有可访问的项目。')}</div>`);
 const t=DB.tenants.find(x=>x.id===p.tenant);
 return UI.page('CREATIVE DESK / 01','AI 创作助手','以当前项目为上下文输入创作目标，后续生产对象均关联该项目。',UI.btn('项目档案','go:workspace/detail','btn'),`
 <div class="grid grid-2"><div class="card"><div class="eyebrow">CURRENT PROJECT / ${UI.esc(p.id)}</div><h2 style="font-size:20px;margin:8px 0">${UI.esc(p.title)}</h2><p class="small muted">${UI.esc(p.genre)} · ${p.episodes} 集 · 归属 ${UI.esc(t?.name||'未知租户')}</p><div class="divider"></div><label class="field-wrap"><span class="field-label">项目创作需求</span><textarea class="field" rows="6" name="creativeBrief" data-project-field="brief" placeholder="输入本项目的题材、核心冲突、人物关系、受众与风格偏好">${UI.esc(p.brief||'')}</textarea></label><div class="grid grid-2 section-gap"><label class="field-wrap"><span class="field-label">目标受众</span><select class="field" name="audience" data-project-field="audience"><option value="">请选择受众</option><option ${p.audience=== '18–35 岁都市观众'?'selected':''}>18–35 岁都市观众</option><option ${p.audience=== '女性成长向'?'selected':''}>女性成长向</option><option ${p.audience=== '泛悬疑受众'?'selected':''}>泛悬疑受众</option></select></label><label class="field-wrap"><span class="field-label">视觉风格</span><select class="field" name="visualStyle" data-project-field="visualStyle"><option value="">请选择风格</option><option ${p.visualStyle=== '电影感写实'?'selected':''}>电影感写实</option><option ${p.visualStyle=== '高饱和商业短剧'?'selected':''}>高饱和商业短剧</option><option ${p.visualStyle=== '国风美学'?'selected':''}>国风美学</option></select></label></div><div class="section-gap">${UI.btn('✳ 生成创意与剧本','script:generate','btn-lime')}</div><div class="tiny muted section-gap">演示交互：记录当前项目的阶段状态，不调用真实模型。</div></div>
 <div class="card card-dark"><div class="eyebrow" style="color:var(--lime)">AI ORCHESTRATOR</div><h2 style="font-size:19px;margin:8px 0 12px">项目 AI 制作统筹</h2><p class="small" style="color:#aebbc2;line-height:1.8">围绕当前项目，将创作需求拆解为可追溯的生产对象，而不是把多个孤立 AI 工具简单堆在一起。</p><div class="divider" style="background:#33404a"></div>${['分析题材与受众定位','构建故事世界观与人物关系','规划分集剧情与集尾钩子','生成完整剧本及对白','预检逻辑、内容与版权风险'].map((x,i)=>`<div class="kpi-line" style="border-color:#33404a"><span style="color:#c6d1d4">${String(i+1).padStart(2,'0')} / ${x}</span><span style="color:var(--lime)">AI</span></div>`).join('')}<div class="notice dark section-gap">人工正式审核点：确认当前项目的剧本版本。审核通过后才进入正式生产。</div></div></div>
 <div class="grid grid-3 section-gap"><div class="card"><div class="card-title">创作输入</div><p class="small muted">题材、核心冲突、人物关系、受众、集数和风格偏好。</p></div><div class="card"><div class="card-title">AI 生成资产</div><p class="small muted">故事大纲、世界观、人物档案、分集剧情、正式剧本候选版本。</p></div><div class="card"><div class="card-title">人工决策</div><p class="small muted">确认故事方向、内容合规与剧本正式版本；不承担专业编剧执行。</p></div></div>`);
}},
{path:'studio/script-review',title:'剧本审核',icon:'▤',permission:'studio',render(){
 const p=App.project();if(!p)return UI.page('HUMAN GATE / SCRIPT','暂无可审核项目','选择当前租户内有待审核剧本的项目。','',`<div class="card">${UI.empty('没有可审核项目','先创建项目并提交创意与剧本生成流程。')}</div>`);
 const version='V'+(p.scriptVersion||3),approved=!!p.scriptApproved;
 return UI.page('HUMAN GATE / SCRIPT','剧本审核台','人工审核节点 A：确认当前项目的故事方向、分集结构、人物设定、逻辑与合规。',UI.btn('打开创作助手','go:studio/brief','btn'),`
 <div class="notice warn">剧本审核是正式生产前的人工决策门。未审核通过的当前项目不能启动导演分镜与后续生产。</div>
 <div class="grid grid-3 section-gap">${UI.metric('当前项目',p.title,'项目编号 '+p.id,'▤')}${UI.metric('剧本版本',version,'当前候选版本','↗')}${UI.metric('审核状态',approved?'已通过':'待审核','以当前项目状态为准','✓')}</div>
 <div class="grid grid-2 section-gap"><div class="card"><div class="card-head"><div><div class="card-title">${UI.esc(p.title)} · 剧本 ${version}</div><div class="card-sub">${UI.esc(p.genre)} · ${p.episodes} 集</div></div>${UI.tag(approved?'已通过':'待审核',approved?'green':'orange')}</div>
 <div class="tabs"><button class="tab active" data-action="tab" data-target="outline">故事大纲</button><button class="tab" data-action="tab" data-target="episodes">分集结构</button><button class="tab" data-action="tab" data-target="risk">合规预检</button></div>
 <div data-tab-panel="outline"><h3 class="section-title">当前项目创作需求</h3><p class="small" style="line-height:1.9;color:#58656c">${UI.esc(p.brief||'该项目尚未填写创作需求。请返回 AI 创作助手补充项目故事方向后再进行审核。')}</p><div class="divider"></div><div class="small"><b>项目状态：</b>${UI.esc(p.status)} · ${UI.esc(p.stage||'待启动')}</div></div>
 <div data-tab-panel="episodes" hidden><div class="kpi-line"><span>计划集数</span><b>${p.episodes} 集</b></div><div class="kpi-line"><span>已完成集数</span><b>${p.done||0} 集</b></div><div class="kpi-line"><span>待制作集数</span><b>${Math.max(0,p.episodes-(p.done||0))} 集</b></div></div>
 <div data-tab-panel="risk" hidden><div class="kpi-line"><span>剧情逻辑检查</span>${UI.tag('演示待复核','orange')}</div><div class="kpi-line"><span>敏感内容检查</span>${UI.tag('需人工确认','orange')}</div><div class="kpi-line"><span>版权素材检查</span>${UI.tag('需核对授权','blue')}</div></div>
 <div class="divider"></div><div class="small muted">审核记录绑定当前项目与版本；版本变更应形成新快照，不覆盖已确认版本。</div></div>
 <div class="card"><div class="card-title">审核决策</div><div class="callout"><div class="callout-icon">✓</div><div><strong>审核提示</strong><p>请结合当前项目创作需求、分集计划和风险提示作出人工判断。原型不伪造真实 AI 检测结果。</p></div></div><div class="field-wrap section-gap"><span class="field-label">审核意见</span><textarea class="field" data-project-field="scriptReviewNote" placeholder="填写通过意见或退回修改建议">${UI.esc(p.scriptReviewNote||'')}</textarea></div><div class="grid grid-2 section-gap">${UI.btn('退回修改','script:return','btn')}${UI.btn(approved?'已确认正式版本':'通过并锁定 '+version,'script:approve','btn-lime')}</div><p class="tiny muted section-gap">通过后形成当前项目的正式版本状态，后续修改应创建新版本并触发影响分析。</p></div></div>`);
}}
]});